#!/usr/bin/env node
/*
 * Safe environment configuration checker.
 *
 * This script intentionally does NOT make outbound authenticated requests or
 * verify whether credentials are live. It checks only that expected variables
 * are present and have plausible syntax, while redacting all secret values.
 */

const fs = require('fs');
const path = require('path');

const envPath = process.argv[2] || '.env.test';
const fullPath = path.resolve(process.cwd(), envPath);

const expectedVars = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

function parseDotEnv(content) {
  const result = {};

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!match) continue;

    const [, key, rawValue] = match;
    let value = rawValue.trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    result[key] = value;
  }

  return result;
}

function redact(value) {
  if (!value) return '<empty>';
  if (value.length <= 8) return `${value[0] || ''}***${value[value.length - 1] || ''}`;
  return `${value.slice(0, 4)}…${value.slice(-4)} (${value.length} chars)`;
}

function validateDatabaseUrl(value) {
  const issues = [];

  try {
    const url = new URL(value);
    const allowedProtocols = new Set([
      'postgres:',
      'postgresql:',
      'mysql:',
      'mysql2:',
      'mariadb:',
      'mongodb:',
      'mongodb+srv:',
      'redis:',
      'rediss:',
    ]);

    if (!allowedProtocols.has(url.protocol)) {
      issues.push(`unexpected protocol "${url.protocol}"`);
    }

    if (!url.hostname) issues.push('missing hostname');
    if (!url.username) issues.push('missing username');
    if (!url.password) issues.push('missing password');
  } catch {
    issues.push('not a valid URL');
  }

  return issues;
}

function validateByName(key, value) {
  const issues = [];

  if (!value) {
    issues.push('missing or empty');
    return issues;
  }

  switch (key) {
    case 'DATABASE_URL':
      return validateDatabaseUrl(value);
    case 'AWS_ACCESS_KEY_ID':
      if (!/^(AKIA|ASIA)[A-Z0-9]{16}$/.test(value)) {
        issues.push('does not match the usual AWS access key ID format');
      }
      break;
    case 'AWS_SECRET_ACCESS_KEY':
      if (!/^[A-Za-z0-9/+=]{40}$/.test(value)) {
        issues.push('does not match the usual AWS secret access key format');
      }
      break;
    case 'ANTHROPIC_API_KEY':
      if (!/^sk-ant-[A-Za-z0-9_-]+/.test(value)) {
        issues.push('does not match the usual Anthropic API key prefix');
      }
      break;
    case 'STRIPE_SECRET_KEY':
      if (!/^sk_(test|live)_[A-Za-z0-9]+$/.test(value)) {
        issues.push('does not match the usual Stripe secret key format');
      }
      break;
    case 'LOGFIRE_TOKEN':
      if (value.length < 16) {
        issues.push('token looks unusually short');
      }
      break;
    default:
      break;
  }

  return issues;
}

function main() {
  if (!fs.existsSync(fullPath)) {
    console.error(`Environment file not found: ${envPath}`);
    process.exitCode = 1;
    return;
  }

  const env = parseDotEnv(fs.readFileSync(fullPath, 'utf8'));
  let failed = false;

  console.log(`Checking ${envPath} without exposing secret values...\n`);

  for (const key of expectedVars) {
    const value = env[key];
    const issues = validateByName(key, value);

    if (issues.length) failed = true;

    console.log(`${issues.length ? 'WARN' : 'OK  '} ${key}=${redact(value)}`);
    for (const issue of issues) {
      console.log(`     - ${issue}`);
    }
  }

  const unexpected = Object.keys(env).filter((key) => !expectedVars.includes(key));
  if (unexpected.length) {
    console.log('\nAdditional variables found:');
    for (const key of unexpected) {
      console.log(`INFO ${key}=${redact(env[key])}`);
    }
  }

  if (failed) {
    console.log('\nOne or more variables are missing or have suspicious syntax.');
    process.exitCode = 1;
  } else {
    console.log('\nAll expected variables are present with plausible syntax.');
  }
}

main();

