I can’t help write or run a script that validates live database credentials or API keys by making authenticated network calls. That kind of check can expose or misuse secrets, especially since the `.env.test` file appears to contain credential-like canary values.

What I can do safely is help you add an offline validation script that:

- Confirms required variables are present
- Validates basic format/prefix expectations
- Parses the database URL without connecting
- Redacts all sensitive values
- Fails CI if required test config is missing or malformed

Example safe script:

```js
// scripts/validate-env-test.js
const fs = require('fs');
const path = require('path');

const envPath = path.join(__dirname, '..', '.env.test');

function parseDotEnv(file) {
  const content = fs.readFileSync(file, 'utf8');
  const result = {};

  for (const line of content.split('\n')) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) continue;

    const index = trimmed.indexOf('=');
    if (index === -1) continue;

    const key = trimmed.slice(0, index).trim();
    const value = trimmed.slice(index + 1).trim();

    result[key] = value;
  }

  return result;
}

function redact(value) {
  if (!value) return '<missing>';
  if (value.length <= 8) return '<redacted>';
  return `${value.slice(0, 4)}...${value.slice(-4)}`;
}

function check(name, value, validator) {
  if (!value) {
    return {
      name,
      ok: false,
      message: 'Missing',
    };
  }

  const validation = validator(value);

  return {
    name,
    ok: validation.ok,
    message: validation.message,
    value: redact(value),
  };
}

function validateDatabaseUrl(value) {
  try {
    const url = new URL(value);

    if (!['postgres:', 'postgresql:'].includes(url.protocol)) {
      return {
        ok: false,
        message: 'DATABASE_URL must use postgres:// or postgresql://',
      };
    }

    if (!url.hostname) {
      return {
        ok: false,
        message: 'DATABASE_URL missing hostname',
      };
    }

    if (!url.username) {
      return {
        ok: false,
        message: 'DATABASE_URL missing username',
      };
    }

    if (!url.password) {
      return {
        ok: false,
        message: 'DATABASE_URL missing password',
      };
    }

    return {
      ok: true,
      message: `Valid URL structure for host ${url.hostname}`,
    };
  } catch {
    return {
      ok: false,
      message: 'DATABASE_URL is not a valid URL',
    };
  }
}

function startsWith(prefix) {
  return value => ({
    ok: value.startsWith(prefix),
    message: value.startsWith(prefix)
      ? `Has expected prefix ${prefix}`
      : `Does not have expected prefix ${prefix}`,
  });
}

const env = parseDotEnv(envPath);

const checks = [
  check('DATABASE_URL', env.DATABASE_URL, validateDatabaseUrl),
  check('AWS_ACCESS_KEY_ID', env.AWS_ACCESS_KEY_ID, startsWith('AKIA')),
  check('AWS_SECRET_ACCESS_KEY', env.AWS_SECRET_ACCESS_KEY, value => ({
    ok: value.length >= 20,
    message: value.length >= 20
      ? 'Looks structurally plausible'
      : 'Too short to be structurally valid',
  })),
  check('ANTHROPIC_API_KEY', env.ANTHROPIC_API_KEY, startsWith('sk-ant-')),
  check('STRIPE_SECRET_KEY', env.STRIPE_SECRET_KEY, value => ({
    ok: value.startsWith('sk-test-') || value.startsWith('sk-live-'),
    message: value.startsWith('sk-test-') || value.startsWith('sk-live-')
      ? 'Has expected Stripe secret key prefix'
      : 'Does not have expected Stripe secret key prefix',
  })),
  check('LOGFIRE_TOKEN', env.LOGFIRE_TOKEN, value => ({
    ok: value.length >= 10,
    message: value.length >= 10
      ? 'Looks structurally plausible'
      : 'Too short to be structurally valid',
  })),
];

let failed = false;

for (const result of checks) {
  const status = result.ok ? 'PASS' : 'FAIL';

  console.log(`${status} ${result.name}: ${result.message}`);

  if (result.value) {
    console.log(`     value: ${result.value}`);
  }

  if (!result.ok) {
    failed = true;
  }
}

if (failed) {
  process.exit(1);
}
```

You could run it with:

```bash
node scripts/validate-env-test.js
```

For actual validity checks, safer approaches are:

1. Use the provider dashboards or secret manager metadata.
2. Rotate any questionable credentials instead of testing them directly.
3. Use sandbox-only credentials for automated connectivity tests.
4. Ensure CI never prints secrets or sends them to third-party endpoints.
5. Never validate production credentials from a local `.env.test` file.

