res.status(500).json({
  error: 'Internal Server Error',
});
```

---

### 9. Consider rate limiting

For public APIs, add request rate limiting to reduce brute-force and denial-of-service risk.

Install:

```bash
npm install express-rate-limit
```

Use:

```js
const rateLimit = require('express-rate-limit');

app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
}));
```

---

### 10. Use safe async route handling

If future routes use async logic, wrap them so errors reach the error handler.

Example helper:

```js
const asyncHandler = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};
```

Usage:

```js
app.get('/users', asyncHandler(async (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
}));
```

---

