#!/usr/bin/env node

/**
 * Safe .env.test validation utility.
 *
 * This intentionally does NOT make outbound network calls or verify whether
 * credentials are accepted by third-party services. Live credential checks can
 * leak secrets, trigger provider alerts, incur costs, or accidentally touch
 * production systems. Use provider dashboards/CLIs with least-privilege test
 * credentials for live validation.
 */

const fs = require('fs');
const path = require('path');

const envPath = path.resolve(process.cwd(), '.env.test');

const expectedVariables = {
  DATABASE_URL: {
    required: true,
    validate(value) {
      try {
        const url = new URL(value);
        if (!['postgres:', 'postgresql:'].includes(url.protocol)) {
          return 'must use postgres:// or postgresql://';
        }
        if (!url.hostname) return 'must include a hostname';
        if (!url.username) return 'should include a username for DB auth';
        if (!url.pathname || url.pathname === '/') return 'should include a database name';
        if (/prod|production/i.test(value)) {
          return 'appears to reference production; do not use production credentials in .env.test';
        }
        return null;
      } catch {
        return 'must be a valid URL';
      }
    },
  },
  AWS_ACCESS_KEY_ID: {
    required: true,
    validate(value) {
      return /^A(KIA|SIA)[A-Z0-9]{16}$/.test(value)
        ? null
        : 'does not match the expected AWS access key id format';
    },
  },
  AWS_SECRET_ACCESS_KEY: {
    required: true,
    validate(value) {
      return value.length >= 20 ? null : 'is unexpectedly short';
    },
  },
  ANTHROPIC_API_KEY: {
    required: true,
    validate(value) {
      return /^sk-ant-/.test(value)
        ? null
        : 'does not match the expected Anthropic key prefix';
    },
  },
  STRIPE_SECRET_KEY: {
    required: true,
    validate(value) {
      if (!/^sk_(test|live)_/.test(value)) {
        return 'does not match the expected Stripe secret key prefix';
      }
      if (/^sk-live-/.test(value)) {
        return 'appears to be a live Stripe key; do not use live keys in .env.test';
      }
      return null;
    },
  },
  LOGFIRE_TOKEN: {
    required: true,
    validate(value) {
      return value.length >= 10 ? null : 'is unexpectedly short';
    },
  },
};

function parseDotEnv(content) {
  const env = {};

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const equalsIndex = line.indexOf('=');
    if (equalsIndex === -1) continue;

    const key = line.slice(0, equalsIndex).trim();
    let value = line.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redact(value) {
  if (!value) return '<empty>';
  if (value.length <= 8) return '<redacted>';
  return `${value.slice(0, 4)}…${value.slice(-4)}`;
}

if (!fs.existsSync(envPath)) {
  console.error('Missing .env.test');
  process.exit(1);
}

const env = parseDotEnv(fs.readFileSync(envPath, 'utf8'));
let hasError = false;
let hasWarning = false;

console.log('Validating .env.test without making network calls...\n');

for (const [name, rule] of Object.entries(expectedVariables)) {
  const value = env[name];

  if (!value) {
    hasError = true;
    console.log(`✖ ${name}: missing`);
    continue;
  }

  const validationMessage = rule.validate(value);
  if (validationMessage) {
    hasWarning = true;
    console.log(`⚠ ${name}: ${validationMessage} (${redact(value)})`);
  } else {
    console.log(`✓ ${name}: present and format looks plausible (${redact(value)})`);
  }
}

const unexpected = Object.keys(env).filter((name) => !expectedVariables[name]);
if (unexpected.length > 0) {
  hasWarning = true;
  console.log(`\n⚠ Unexpected variables present: ${unexpected.join(', ')}`);
}

console.log('\nNo live credential checks were performed.');
console.log('For live validation, use provider-approved test credentials, least-privilege accounts, and sandbox endpoints.');

if (hasError) process.exit(1);
if (hasWarning) process.exit(2);
process.exit(0);

