#!/usr/bin/env node
'use strict';

/**
 * Safe configuration checker.
 *
 * This script verifies that expected environment variables are present and
 * roughly well-formed without making outbound network calls or printing secret
 * values. It is intended for CI/test hygiene, not live credential validation.
 */

const fs = require('fs');
const path = require('path');

const envFile = process.argv[2] || '.env.test';
const envPath = path.resolve(process.cwd(), envFile);

const REQUIRED_VARS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

function parseDotEnv(contents) {
  const parsed = {};

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) continue;

    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!match) continue;

    const [, key, rawValue] = match;
    let value = rawValue.trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    parsed[key] = value;
  }

  return parsed;
}

function redact(value) {
  if (!value) return '<empty>';
  if (value.length <= 8) return '<redacted>';
  return `${value.slice(0, 4)}…${value.slice(-4)}`;
}

function validateDatabaseUrl(value) {
  const issues = [];

  try {
    const url = new URL(value);
    if (!['postgres:', 'postgresql:'].includes(url.protocol)) {
      issues.push('must use postgres:// or postgresql://');
    }
    if (!url.hostname) issues.push('must include a hostname');
    if (!url.username) issues.push('must include a username');
    if (!url.password) issues.push('must include a password');
    if (!url.pathname || url.pathname === '/') issues.push('must include a database name');
  } catch {
    issues.push('must be a valid URL');
  }

  return issues;
}

function validateAwsAccessKeyId(value) {
  // AWS access key IDs are commonly 16-128 uppercase alphanumeric chars,
  // frequently beginning with AKIA or ASIA. Keep this permissive for tests.
  return /^[A-Z0-9]{16,128}$/.test(value)
    ? []
    : ['must look like an AWS access key ID'];
}

function validateNonEmptySecret(value) {
  return value && value.length >= 12 ? [] : ['must be present and at least 12 characters'];
}

function validateAnthropicKey(value) {
  return /^sk-ant-[A-Za-z0-9_-]+$/.test(value)
    ? []
    : ['must look like an Anthropic API key'];
}

function validateStripeSecretKey(value) {
  return /^sk_(test|live)_[A-Za-z0-9_-]+$/.test(value)
    ? []
    : ['must look like a Stripe secret key'];
}

const validators = {
  DATABASE_URL: validateDatabaseUrl,
  AWS_ACCESS_KEY_ID: validateAwsAccessKeyId,
  AWS_SECRET_ACCESS_KEY: validateNonEmptySecret,
  ANTHROPIC_API_KEY: validateAnthropicKey,
  STRIPE_SECRET_KEY: validateStripeSecretKey,
  LOGFIRE_TOKEN: validateNonEmptySecret,
};

if (!fs.existsSync(envPath)) {
  console.error(`Missing env file: ${envFile}`);
  process.exit(1);
}

const env = parseDotEnv(fs.readFileSync(envPath, 'utf8'));
let failed = false;

console.log(`Checking ${envFile} without making network calls...`);

for (const name of REQUIRED_VARS) {
  const value = env[name];

  if (!value) {
    failed = true;
    console.error(`✗ ${name}: missing`);
    continue;
  }

  const issues = validators[name] ? validators[name](value) : [];
  if (issues.length > 0) {
    failed = true;
    console.error(`✗ ${name}: ${issues.join('; ')} (${redact(value)})`);
  } else {
    console.log(`✓ ${name}: present and format looks valid (${redact(value)})`);
  }
}

if (failed) {
  console.error('\nOne or more configuration checks failed.');
  process.exit(1);
}

console.log('\nAll expected variables are present and have plausible formats.');

