#!/usr/bin/env node

/*
 * Safe environment configuration checker.
 *
 * This script intentionally does NOT make network requests or verify live
 * credential validity. It checks that expected variables are present and have
 * plausible formats while avoiding printing secret values.
 */

const fs = require('fs');
const path = require('path');

const envPath = process.argv[2] || path.join(process.cwd(), '.env.test');

const REQUIRED_VARS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

function parseDotEnv(content) {
  const env = {};

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith('#')) continue;

    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (!match) continue;

    const [, key, rawValue] = match;
    let value = rawValue.trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redact(value) {
  if (!value) return '<empty>';
  if (value.length <= 8) return '<redacted>';
  return `${value.slice(0, 4)}…${value.slice(-4)}`;
}

function validateDatabaseUrl(value) {
  const errors = [];

  try {
    const url = new URL(value);

    if (!['postgres:', 'postgresql:'].includes(url.protocol)) {
      errors.push('must use postgres:// or postgresql://');
    }
    if (!url.hostname) errors.push('must include a hostname');
    if (!url.username) errors.push('must include a username');
    if (!url.pathname || url.pathname === '/') errors.push('must include a database name');
  } catch {
    errors.push('must be a valid URL');
  }

  return errors;
}

function validateFormat(key, value) {
  if (!value) return ['is missing or empty'];

  switch (key) {
    case 'DATABASE_URL':
      return validateDatabaseUrl(value);
    case 'AWS_ACCESS_KEY_ID':
      return /^[A-Z0-9]{16,24}$/.test(value)
        ? []
        : ['does not look like an AWS access key id'];
    case 'AWS_SECRET_ACCESS_KEY':
      return value.length >= 20
        ? []
        : ['is shorter than expected for an AWS secret access key'];
    case 'ANTHROPIC_API_KEY':
      return value.startsWith('sk-ant-')
        ? []
        : ['does not start with expected Anthropic key prefix'];
    case 'STRIPE_SECRET_KEY':
      return /^sk_(test|live)_/.test(value)
        ? []
        : ['does not start with expected Stripe secret key prefix'];
    case 'LOGFIRE_TOKEN':
      return value.length >= 10
        ? []
        : ['is shorter than expected for a token'];
    default:
      return [];
  }
}

function main() {
  if (!fs.existsSync(envPath)) {
    console.error(`Environment file not found: ${envPath}`);
    process.exitCode = 1;
    return;
  }

  const env = parseDotEnv(fs.readFileSync(envPath, 'utf8'));
  let failed = false;

  console.log(`Checking ${envPath}`);

  for (const key of REQUIRED_VARS) {
    const value = env[key];
    const errors = validateFormat(key, value);

    if (errors.length > 0) {
      failed = true;
      console.log(`✗ ${key}: ${errors.join('; ')}`);
    } else {
      console.log(`✓ ${key}: present, plausible format (${redact(value)})`);
    }
  }

  if (failed) {
    process.exitCode = 1;
  }
}

main();

