#!/usr/bin/env node

/*
 * Safely validate .env.test without making network calls or printing secrets.
 *
 * This script checks whether expected variables are present and have plausible
 * formats. It intentionally does NOT verify live credential validity against
 * databases or third-party APIs, because doing so can expose or misuse secrets.
 */

const fs = require('fs');
const path = require('path');

const envPath = path.resolve(process.cwd(), '.env.test');

function parseDotEnv(contents) {
  const env = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    let value = line.slice(eqIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redact(value) {
  if (!value) return '<empty>';
  if (value.length <= 8) return '<redacted>';
  return `${value.slice(0, 4)}…${value.slice(-4)}`;
}

function check(name, value, validator, description) {
  if (!value) {
    return { name, ok: false, message: 'missing or empty' };
  }

  try {
    const result = validator(value);
    return {
      name,
      ok: result === true,
      message: result === true ? description : result,
      value: redact(value),
    };
  } catch (error) {
    return { name, ok: false, message: error.message, value: redact(value) };
  }
}

function validateDatabaseUrl(value) {
  const url = new URL(value);
  const allowedProtocols = new Set(['postgres:', 'postgresql:']);

  if (!allowedProtocols.has(url.protocol)) {
    return 'must use postgres:// or postgresql://';
  }
  if (!url.hostname) return 'must include a hostname';
  if (!url.username) return 'must include a username';
  if (!url.password) return 'must include a password';
  if (!url.pathname || url.pathname === '/') return 'must include a database name';

  return true;
}

const validators = [
  [
    'DATABASE_URL',
    validateDatabaseUrl,
    'present and shaped like a PostgreSQL connection URL',
  ],
  [
    'AWS_ACCESS_KEY_ID',
    (value) => /^A(KIA|SIA)[A-Z0-9]{16}$/.test(value) || 'must look like an AWS access key id',
    'present and shaped like an AWS access key id',
  ],
  [
    'AWS_SECRET_ACCESS_KEY',
    (value) => value.length >= 20 || 'must be at least 20 characters',
    'present and non-trivially long',
  ],
  [
    'ANTHROPIC_API_KEY',
    (value) => value.startsWith('sk-ant-') || 'must start with sk-ant-',
    'present and has expected Anthropic key prefix',
  ],
  [
    'STRIPE_SECRET_KEY',
    (value) => /^sk_(test|live)_/.test(value) || 'must start with sk-test- or sk-live-',
    'present and has expected Stripe secret key prefix',
  ],
  [
    'LOGFIRE_TOKEN',
    (value) => value.length >= 10 || 'must be at least 10 characters',
    'present and non-trivially long',
  ],
];

if (!fs.existsSync(envPath)) {
  console.error('.env.test not found');
  process.exit(1);
}

const env = parseDotEnv(fs.readFileSync(envPath, 'utf8'));
const results = validators.map(([name, validator, description]) =>
  check(name, env[name], validator, description),
);

for (const result of results) {
  const status = result.ok ? 'PASS' : 'FAIL';
  const value = result.value ? ` (${result.value})` : '';
  console.log(`${status} ${result.name}${value}: ${result.message}`);
}

const failures = results.filter((result) => !result.ok);
if (failures.length > 0) {
  console.error(`\n${failures.length} validation check(s) failed.`);
  process.exit(1);
}

console.log('\nAll .env.test variables are present and have plausible offline formats.');

