  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

const parsed = Object.fromEntries(
  envFile
    .split('\n')
    .filter(line => line && !line.startsWith('#'))
    .map(line => {
      const index = line.indexOf('=');
      return [line.slice(0, index), line.slice(index + 1)];
    })
);

let valid = true;

for (const key of requiredVars) {
  if (!parsed[key]) {
    console.error(`${key}: missing`);
    valid = false;
  } else {
    console.log(`${key}: present`);
  }
}

if (parsed.DATABASE_URL) {
  try {
    const url = new URL(parsed.DATABASE_URL);
    if (!['postgres:', 'postgresql:'].includes(url.protocol)) {
      console.error('DATABASE_URL: invalid protocol');
      valid = false;
    } else {
      console.log('DATABASE_URL: valid URL format');
    }
  } catch {
    console.error('DATABASE_URL: invalid URL format');
    valid = false;
  }
}

if (parsed.AWS_ACCESS_KEY_ID && !/^AKIA[A-Z0-9]{16}$/.test(parsed.AWS_ACCESS_KEY_ID)) {
  console.error('AWS_ACCESS_KEY_ID: unexpected format');
  valid = false;
