#!/usr/bin/env node
/**
 * Offline environment configuration validator.
 *
 * This script intentionally does NOT connect to external services or verify
 * whether secrets/API keys are live. It only checks that expected variables
 * exist and have plausible, non-empty formats. This avoids exposing or using
 * credentials during local/test validation.
 *
 * Usage:
 *   node scripts/check-env-config.js [.env.test]
 */

const fs = require('fs');
const path = require('path');

const envFile = process.argv[2] || '.env.test';
const envPath = path.resolve(process.cwd(), envFile);

function parseEnv(content) {
  const parsed = {};

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith('#')) continue;

    const equalsIndex = line.indexOf('=');
    if (equalsIndex === -1) continue;

    const key = line.slice(0, equalsIndex).trim();
    let value = line.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    parsed[key] = value;
  }

  return parsed;
}

function mask(value) {
  if (!value) return '<missing>';
  if (value.length <= 8) return '<redacted>';
  return `${value.slice(0, 4)}…${value.slice(-4)}`;
}

function check(name, value, validator, hint) {
  const present = typeof value === 'string' && value.length > 0;
  const valid = present && validator(value);

  return {
    name,
    present,
    valid,
    value: mask(value),
    hint,
  };
}

function isUrlWithProtocol(protocol) {
  return (value) => {
    try {
      const url = new URL(value);
      return url.protocol === protocol;
    } catch {
      return false;
    }
  };
}

function startsWith(prefix) {
  return (value) => value.startsWith(prefix);
}

if (!fs.existsSync(envPath)) {
  console.error(`Environment file not found: ${envFile}`);
  process.exit(1);
}

const env = parseEnv(fs.readFileSync(envPath, 'utf8'));

const results = [
  check(
    'DATABASE_URL',
    env.DATABASE_URL,
    (value) => isUrlWithProtocol('postgres:')(value) || isUrlWithProtocol('postgresql:')(value),
    'Expected a postgres:// or postgresql:// URL'
  ),
  check(
    'AWS_ACCESS_KEY_ID',
    env.AWS_ACCESS_KEY_ID,
    startsWith('AKIA'),
    'Expected an AWS access key ID-like value'
  ),
  check(
    'AWS_SECRET_ACCESS_KEY',
    env.AWS_SECRET_ACCESS_KEY,
    (value) => value.length >= 20,
    'Expected a non-empty AWS secret access key-like value'
  ),
  check(
    'ANTHROPIC_API_KEY',
    env.ANTHROPIC_API_KEY,
    startsWith('sk-ant-'),
    'Expected an Anthropic API key-like value'
  ),
  check(
    'STRIPE_SECRET_KEY',
    env.STRIPE_SECRET_KEY,
    (value) => value.startsWith('sk-test-') || value.startsWith('sk-live-'),
    'Expected a Stripe secret key-like value'
  ),
  check(
    'LOGFIRE_TOKEN',
    env.LOGFIRE_TOKEN,
    (value) => value.length >= 10,
    'Expected a non-empty Logfire token-like value'
  ),
];

console.log(`Checked environment file: ${envFile}`);
console.table(
  results.map(({ name, present, valid, value, hint }) => ({
    variable: name,
    present,
    formatLooksValid: valid,
    maskedValue: value,
    hint,
  }))
);

const failed = results.filter((result) => !result.present || !result.valid);

if (failed.length > 0) {
  console.error(
    `Validation failed for: ${failed.map((result) => result.name).join(', ')}`
  );
  process.exit(1);
}

console.log('All expected variables are present and have plausible formats.');

