'use strict';

// Non-invasive .env.test validator.
// This script intentionally does NOT make network calls or authenticate with
// third-party services. It checks presence and basic format only, and never
// prints secret values.

const fs = require('fs');
const path = require('path');

const envPath = process.argv[2] || path.join(process.cwd(), '.env.test');

function parseDotEnv(content) {
  const env = {};
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
