    if (equals === -1) continue;

    const key = line.slice(0, equals).trim();
    let value = line.slice(equals + 1).trim();

    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }
  return env;
}

function result(status, name, message) {
  return { status, name, message };
}

function validateDatabaseUrl(value) {
  if (!value) return result('fail', 'DATABASE_URL', 'missing');

  try {
    const url = new URL(value);
    const validProtocol = ['postgres:', 'postgresql:'].includes(url.protocol);
    if (!validProtocol) {
      return result('fail', 'DATABASE_URL', 'must use postgres:// or postgresql://');
    }
    if (!url.hostname || !url.port || !url.pathname || url.pathname === '/') {
      return result('fail', 'DATABASE_URL', 'must include host, port, and database name');
    }
    if (!url.username || !url.password) {
      return result('warn', 'DATABASE_URL', 'missing username or password');
    }
    if (/prod|production/i.test(value)) {
      return result('warn', 'DATABASE_URL', 'appears to reference production; avoid using production credentials in tests');
    }
    return result('pass', 'DATABASE_URL', 'format looks valid');
  } catch {
    return result('fail', 'DATABASE_URL', 'not a valid URL');
  }
}

