/*
 * Safe .env.test validator.
 *
 * This script intentionally does NOT make network requests or authenticate with
 * third-party services. It validates presence, basic format, and highlights
 * potentially risky configuration without printing secret values.
 */

const fs = require('fs');
const path = require('path');

