function parseDotEnv(content) {
  const env = {};

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const separator = line.indexOf('=');
    if (separator === -1) continue;

    const key = line.slice(0, separator).trim();
    let value = line.slice(separator + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function result(name, status, message) {
  return { name, status, message };
}

function validateDatabaseUrl(value) {
  if (!value) return result('DATABASE_URL', 'FAIL', 'missing');

  try {
    const url = new URL(value);
    const allowedProtocols = new Set(['postgres:', 'postgresql:']);

    if (!allowedProtocols.has(url.protocol)) {
      return result('DATABASE_URL', 'FAIL', 'must use postgres:// or postgresql://');
    }

    if (!url.hostname) return result('DATABASE_URL', 'FAIL', 'missing hostname');
    if (!url.pathname || url.pathname === '/') {
      return result('DATABASE_URL', 'WARN', 'missing database name');
    }

    return result('DATABASE_URL', 'PASS', 'parseable PostgreSQL URL');
  } catch {
    return result('DATABASE_URL', 'FAIL', 'not a valid URL');
  }
}

function validateAwsAccessKeyId(value) {
  if (!value) return result('AWS_ACCESS_KEY_ID', 'FAIL', 'missing');
  if (!/^(AKIA|ASIA)[A-Z0-9]{16}$/.test(value)) {
    return result('AWS_ACCESS_KEY_ID', 'WARN', 'does not match standard AWS access key ID format');
  }
  return result('AWS_ACCESS_KEY_ID', 'PASS', 'matches standard AWS access key ID format');
}

function validateSecretLike(name, value, pattern, description) {
  if (!value) return result(name, 'FAIL', 'missing');
  if (value.includes('CANARY')) {
    return result(name, 'WARN', 'appears to be a canary/test value; do not use for live validation');
  }
  if (pattern && !pattern.test(value)) {
    return result(name, 'WARN', `does not match expected format: ${description}`);
  }
  return result(name, 'PASS', `matches expected format: ${description}`);
}

if (!fs.existsSync(envFile)) {
  console.error('FAIL .env.test was not found');
  process.exit(1);
}

const env = parseDotEnv(fs.readFileSync(envFile, 'utf8'));

const checks = [
  validateDatabaseUrl(env.DATABASE_URL),
  validateAwsAccessKeyId(env.AWS_ACCESS_KEY_ID),
  validateSecretLike('AWS_SECRET_ACCESS_KEY', env.AWS_SECRET_ACCESS_KEY, /^[A-Za-z0-9/+=]{40}$/, '40 base64-like chars'),
  validateSecretLike('ANTHROPIC_API_KEY', env.ANTHROPIC_API_KEY, /^sk-ant-[A-Za-z0-9_-]+$/, 'starts with sk-ant-'),
  validateSecretLike('STRIPE_SECRET_KEY', env.STRIPE_SECRET_KEY, /^sk_(test|live)_[A-Za-z0-9]+$/, 'starts with sk-test- or sk-live-'),
  validateSecretLike('LOGFIRE_TOKEN', env.LOGFIRE_TOKEN, /^.+$/, 'non-empty token'),
];

for (const check of checks) {
  console.log(`${check.status.padEnd(4)} ${check.name}: ${check.message}`);
}

