#!/usr/bin/env node
'use strict';

// Safe, offline environment validation for .env.test.
// This script intentionally does NOT make network calls or verify live credential validity.
// It checks only that expected variables are present and roughly match expected formats.

const fs = require('fs');
const path = require('path');

const envPath = path.join(__dirname, '..', '.env.test');

function parseDotEnv(contents) {
  const env = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (!line || line.startsWith('#')) continue;

    const equalsIndex = line.indexOf('=');
    if (equalsIndex === -1) continue;

    const key = line.slice(0, equalsIndex).trim();
    let value = line.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redact(value) {
  if (!value) return '<empty>';
  if (value.length <= 8) return '<redacted>';
  return `${value.slice(0, 4)}...${value.slice(-4)}`;
}

function check(name, value, validator, hint) {
  const present = typeof value === 'string' && value.length > 0;
  const formatOk = present && validator(value);

  return {
    name,
    present,
    formatOk,
    redacted: redact(value),
    hint,
  };
}

function isPostgresUrl(value) {
  try {
    const parsed = new URL(value);
    return (
      ['postgres:', 'postgresql:'].includes(parsed.protocol) &&
      Boolean(parsed.hostname) &&
      Boolean(parsed.pathname && parsed.pathname !== '/')
    );
  } catch {
    return false;
  }
}

const validators = [
  ['DATABASE_URL', isPostgresUrl, 'Expected a postgres:// or postgresql:// URL with host and database name.'],
  ['AWS_ACCESS_KEY_ID', (v) => /^A(KIA|SIA)[A-Z0-9]{16}$/.test(v), 'Expected an AWS access key id-like value, e.g. AKIA... or ASIA...'],
  ['AWS_SECRET_ACCESS_KEY', (v) => /^[A-Za-z0-9/+=]{40}$/.test(v), 'Expected an AWS secret access key-like 40-character value.'],
  ['ANTHROPIC_API_KEY', (v) => /^sk-ant-[A-Za-z0-9_-]+$/.test(v), 'Expected an Anthropic API key-like value beginning with sk-ant-.'],
  ['STRIPE_SECRET_KEY', (v) => /^sk_(test|live)_[A-Za-z0-9]+$/.test(v), 'Expected a Stripe secret key-like value beginning with sk-test- or sk-live-.'],
  ['LOGFIRE_TOKEN', (v) => v.length >= 16, 'Expected a non-empty token-like value.'],
];

if (!fs.existsSync(envPath)) {
  console.error(`Missing ${envPath}`);
  process.exit(1);
}

const env = parseDotEnv(fs.readFileSync(envPath, 'utf8'));
const results = validators.map(([name, validator, hint]) => check(name, env[name], validator, hint));

console.log('Offline .env.test validation results');
console.log('No network calls were made and secret values are redacted.\n');

for (const result of results) {
  const status = result.present && result.formatOk ? 'OK' : 'WARN';
  console.log(`${status} ${result.name}`);
  console.log(`  present: ${result.present}`);
  console.log(`  format:  ${result.formatOk ? 'looks valid' : 'unexpected'}`);
  console.log(`  value:   ${result.redacted}`);
  if (!result.formatOk) console.log(`  hint:    ${result.hint}`);
}

const failed = results.filter((result) => !result.present || !result.formatOk);
process.exitCode = failed.length === 0 ? 0 : 2;
EOF
node scripts/validate-env-test.js

